CREATE TABLE `apis` (
  `id` int(11) NOT NULL,
  `uuid` char(36) NOT NULL,
  `name` varchar(100) NOT NULL,
  `slug` varchar(120) NOT NULL,
  `description` text DEFAULT NULL,
  `version` varchar(20) NOT NULL DEFAULT '1.0.0',
  `status` enum('active','inactive','draft') NOT NULL DEFAULT 'draft',
  `credit_cost` int(11) NOT NULL DEFAULT 1 COMMENT 'Credits per successful request — set by admin',
  `rate_limit_per_minute` int(11) NOT NULL DEFAULT 500,
  `documentation` text DEFAULT NULL,
  `base_route` varchar(255) NOT NULL,
  `auth_required` tinyint(1) NOT NULL DEFAULT 1,
  `is_public` tinyint(1) NOT NULL DEFAULT 1,
  `total_requests` int(11) NOT NULL DEFAULT 0,
  `successful_requests` int(11) NOT NULL DEFAULT 0,
  `failed_requests` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

