INSERT INTO `apis` (`id`, `uuid`, `name`, `slug`, `description`, `version`, `status`, `credit_cost`, `rate_limit_per_minute`, `documentation`, `base_route`, `auth_required`, `is_public`, `total_requests`, `successful_requests`, `failed_requests`, `created_at`, `updated_at`, `deleted_at`) VALUES
(14, '24167f8e-1cd1-4abb-95e2-5a31084c61e5', 'Mathematics', 'mathematics', 'A multi-operation API for rapidly processing various mathematical calculations.', '1.0.0', 'active', 2, 30, '## Mathematics API\n\nPerform math operations.\n\n### Endpoint\n```\nGET /gateway/mathematics/math?op=add&a=1&b=2\n```\n\n### Operations\nadd, subtract, multiply, divide, power, sqrt, modulo', '/gateway/mathematics', 1, 1, 0, 0, 0, '2026-09-03 09:56:25', '2026-09-11 14:02:44', NULL),
(15, '0b665f26-8e90-46a1-b8ab-568cb068af1e', 'UUID', 'uuid', 'API for instantly generating Universally Unique Identifiers (UUIDs).', '1.0.0', 'active', 2, 30, '## UUID API\n\nGenerate and validate UUID v4.\n\n### Endpoint\n```\nGET /gateway/uuid/generator\n```', '/gateway/uuid', 1, 1, 0, 0, 0, '2026-09-03 10:33:48', '2026-09-11 14:02:47', NULL),
(16, 'eaf8d41e-39db-49e3-b841-0a4f5966d475', 'Password', 'password', 'API for generating secure random passwords.', '1.0.0', 'active', 2, 30, '## Password API\n\nGenerate secure random passwords.\n\n### Endpoint\n```\nGET /gateway/password/generator?length=16\n```', '/gateway/password', 1, 1, 0, 0, 0, '2026-09-03 10:42:08', '2026-09-11 14:02:49', NULL),
(17, '42841f8a-d568-4fe1-a2b1-6a6a11e54df7', 'Hashing', 'hashing', 'API for securely generating hashes from data.', '1.0.0', 'active', 2, 30, '## Hashing API\n\nGenerate MD5/SHA hashes.\n\n### Endpoint\n```\nGET /gateway/hashing/md5?text=hello\nGET /gateway/hashing/sha?text=hello&algo=256\n```', '/gateway/hashing', 1, 1, 0, 0, 0, '2026-09-03 11:57:18', '2026-09-11 14:02:52', NULL),
(18, '4d3ec636-f232-44ed-a936-406388412221', 'Base64', 'base64', 'API for encoding and decoding Base64-formatted data.', '1.0.0', 'active', 2, 30, '## Base64 API\n\nEncode and decode Base64.\n\n### Endpoint\n```\nPOST /gateway/base64/encode { \"text\": \"hello\" }\nPOST /gateway/base64/decode { \"text\": \"aGVsbG8=\" }\n```', '/gateway/base64', 1, 1, 0, 0, 0, '2026-09-03 12:08:20', '2026-09-11 14:02:53', NULL),
(19, 'a78258a9-38b4-4d05-9cb4-5a268bec78d2', 'Percentage', 'percentage', 'API to calculate percentages, changes, and proportions instantly.', '1.0.0', 'active', 2, 30, '## Percentage API\n\nCalculate percentages.\n\n### Endpoint\n```\nGET /gateway/percentage/generator?value=50&total=200\n```', '/gateway/percentage', 1, 1, 0, 0, 0, '2026-09-04 08:38:42', '2026-09-11 14:02:55', NULL),
(20, 'ad57ca25-cb05-4bc2-8b7f-e0a1d7d4d179', 'BMI', 'bmi', 'API to calculate Body Mass Index (BMI) instantly.', '1.0.0', 'active', 2, 30, '## BMI API\n\nCalculate Body Mass Index.\n\n### Endpoint\n```\nGET /gateway/bmi/generator?weight=70&height=175\n```', '/gateway/bmi', 1, 1, 0, 0, 0, '2026-09-04 08:46:47', '2026-09-11 14:02:56', NULL),
(21, 'b7a0bb0c-7f9f-4a0e-ba0b-0db7ec3384c1', 'Age', 'age', 'API to calculate exact age based on birthdate.', '1.0.0', 'active', 2, 30, '## Age API\n\nCalculate age from birthdate.\n\n### Endpoint\n```\nGET /gateway/age/generator?birthdate=1990-01-01\n```', '/gateway/age', 1, 1, 0, 0, 0, '2026-09-04 08:49:40', '2026-09-11 14:02:57', NULL),
(22, '3d3a4a39-3c1e-4562-975b-9476a657d5ee', 'Discount', 'discount', 'API to calculate discounted prices and final savings instantly.', '1.0.0', 'active', 2, 30, '## Discount API\n\nCalculate discounted prices.\n\n### Endpoint\n```\nGET /gateway/discount/generator?price=100000&discount=20\n```', '/gateway/discount', 1, 1, 0, 0, 0, '2026-09-04 08:53:00', '2026-09-11 14:02:58', NULL),
(23, '3d64ec55-49b2-4126-a5fb-d0e9bfdaee0f', 'Tax', 'tax', 'API to calculate taxes based on income and region.', '1.0.0', 'active', 2, 30, '## Tax API\n\nCalculate taxes.\n\n### Endpoint\n```\nGET /gateway/tax/generator?income=50000000&rate=10\n```', '/gateway/tax', 1, 1, 0, 0, 0, '2026-09-04 09:07:14', '2026-09-11 14:03:00', NULL),
(24, 'e369306d-0e42-40d6-baf2-e8d12dd16eac', 'Tips', 'tips', 'API to calculate tips and split bills instantly.', '1.0.0', 'active', 2, 30, '## Tips API\n\nCalculate tips and split bills.\n\n### Endpoint\n```\nGET /gateway/tips/generator?bill=100000&tip=10&split=2\n```', '/gateway/tips', 1, 1, 0, 0, 0, '2026-09-04 09:24:03', '2026-09-11 14:03:02', NULL),
(25, '223d673d-5a96-4a5f-bc2d-6320b6f2d5e8', 'Interest', 'interest', 'API to calculate compound interest and investment growth instantly.', '1.0.0', 'active', 2, 30, '## Interest API\n\nCalculate compound interest.\n\n### Endpoint\n```\nGET /gateway/interest/generator?principal=1000000&rate=5&years=10\n```', '/gateway/interest', 1, 1, 0, 0, 0, '2026-09-04 09:27:11', '2026-09-11 14:03:03', NULL),
(26, '0fcc1d6a-148f-44ed-8d16-e85fea6fb91d', 'Average', 'average', 'API to calculate the average of a dataset instantly.', '1.0.0', 'active', 2, 30, '## Average API\n\nCalculate average of numbers.\n\n### Endpoint\n```\nGET /gateway/average/generator?numbers=10,20,30,40\n```', '/gateway/average', 1, 1, 0, 0, 0, '2026-09-04 09:29:18', '2026-09-11 14:03:04', NULL),
(27, '0e64c973-0992-4fab-9441-94e2994e058e', 'Equation', 'equation', 'API to solve mathematical equations and expressions instantly.', '1.0.0', 'active', 2, 30, '## Equation API\n\nSolve linear equations.\n\n### Endpoint\n```\nGET /gateway/equation/generator?equation=2x+5=15\n```', '/gateway/equation', 1, 1, 0, 0, 0, '2026-09-04 09:32:08', '2026-09-11 14:03:15', NULL),
(28, 'e3fdd457-7833-4537-8dbe-328e0d916b12', 'Length', 'length', 'API for Length Converter.', '1.0.0', 'active', 2, 30, '## Length Converter\n\nConvert length units.\n\n### Endpoint\n```\nGET /gateway/length/generator?value=1&from=meter&to=feet\n```', '/gateway/length', 1, 1, 0, 0, 0, '2026-09-05 13:18:55', '2026-09-11 14:03:17', NULL),
(29, '5d2fc9b2-0c45-4bd7-a1c1-2840de91beed', 'Weight', 'weight', 'Api for Weight Converter', '1.0.0', 'active', 2, 30, '## Weight Converter\n\nConvert weight units.\n\n### Endpoint\n```\nGET /gateway/weight/generator?value=1&from=kg&to=pound\n```', '/gateway/weight', 1, 1, 0, 0, 0, '2026-09-05 13:24:11', '2026-09-11 14:03:18', NULL),
(30, 'df0d0e89-0dbf-4909-97bc-3f136ce39a1d', 'Temperature', 'temperature', 'Api for Temperature Converter', '1.0.0', 'active', 2, 30, '## Temperature Converter\n\nConvert temperature units.\n\n### Endpoint\n```\nGET /gateway/temperature/generator?value=100&from=celsius&to=fahrenheit\n```', '/gateway/temperature', 1, 1, 0, 0, 0, '2026-09-05 13:26:38', '2026-09-11 14:03:20', NULL),
(31, '8a8a7b01-2c4f-4cee-bfc0-0d01bb310460', 'Area', 'area', 'Api for Area Converter', '1.0.0', 'active', 2, 30, '## Area Converter\n\nConvert area units.\n\n### Endpoint\n```\nGET /gateway/area/generator?value=1&from=sqm&to=sqft\n```', '/gateway/area', 1, 1, 0, 0, 0, '2026-09-05 13:28:29', '2026-09-11 14:03:22', NULL),
(32, '3ca814e6-0c6f-4939-804f-c50c378db5ac', 'Volume', 'volume', 'Api for Volume Converter', '1.0.0', 'active', 2, 30, '## Volume Converter\n\nConvert volume units.\n\n### Endpoint\n```\nGET /gateway/volume/generator?value=1&from=liter&to=gallon\n```', '/gateway/volume', 1, 1, 0, 0, 0, '2026-09-05 13:31:52', '2026-09-11 14:03:23', NULL),
(33, '36ddc839-25cd-4d58-a22b-2f56f897277e', 'Speed', 'speed', 'Api for Speed Converter', '1.0.0', 'active', 2, 30, '## Speed Converter\n\nConvert speed units.\n\n### Endpoint\n```\nGET /gateway/speed/generator?value=100&from=kmh&to=mph\n```', '/gateway/speed', 1, 1, 0, 0, 0, '2026-09-05 13:36:32', '2026-09-11 14:03:24', NULL),
(34, '7e56103e-8630-4a96-9c74-9cd54e08649f', 'Time', 'time', 'Api for Time Converter', '1.0.0', 'active', 2, 30, '## Time Converter\n\nConvert time units.\n\n### Endpoint\n```\nGET /gateway/time/generator?value=1&from=hour&to=minute\n```', '/gateway/time', 1, 1, 0, 0, 0, '2026-09-05 13:38:34', '2026-09-11 14:03:26', NULL),
(35, '88714e93-cef5-4b0a-a7ff-907066685bdc', 'DataSize', 'datasize', 'Api for Data Size Converter', '1.0.0', 'active', 2, 30, '## Data Size Converter\n\nConvert data storage units.\n\n### Endpoint\n```\nGET /gateway/datasize/generator?value=1&from=gb&to=mb\n```', '/gateway/datasize', 1, 1, 0, 0, 0, '2026-09-05 13:40:56', '2026-09-11 14:03:28', NULL),
(36, '60bf8c77-05b2-4660-962a-f56dd20bd5bc', 'Angle', 'angle', 'Api for Angle Converter', '1.0.0', 'active', 2, 30, '## Angle Converter\n\nConvert angle units.\n\n### Endpoint\n```\nGET /gateway/angle/generator?value=90&from=degree&to=radian\n```', '/gateway/angle', 1, 1, 0, 0, 0, '2026-09-05 13:42:55', '2026-09-11 14:03:30', NULL),
(37, 'ad7e1973-934a-4116-a55a-86840ce6c754', 'Pressure', 'pressure', 'Api for Pressure Converter', '1.0.0', 'active', 2, 30, '## Pressure Converter\n\nConvert pressure units.\n\n### Endpoint\n```\nGET /gateway/pressure/generator?value=1&from=bar&to=psi\n```', '/gateway/pressure', 1, 1, 0, 0, 0, '2026-09-05 13:44:48', '2026-09-11 14:03:33', NULL),
(38, '9ee4e23b-8b6d-4290-b4ee-40b3a69601b3', 'Text Counter', 'text-counter', 'Api for Text Counter', '1.0.0', 'active', 2, 30, '## Text Counter\n\nCount words, characters, lines.\n\n### Endpoint\n```\nGET /gateway/text-counter/generator?text=hello world\n```', '/gateway/text-counter', 1, 1, 0, 0, 0, '2026-09-05 13:46:24', '2026-09-11 14:03:35', NULL),
(39, '5ddd6ad4-5f45-40aa-b13f-24219cda02e4', 'Case Converter', 'case-converter', 'Api for Case Converter', '1.0.0', 'active', 2, 30, '## Case Converter\n\nConvert text case.\n\n### Endpoint\n```\nGET /gateway/case-converter/generator?text=hello world&case=upper\n```', '/gateway/case-converter', 1, 1, 0, 0, 0, '2026-09-05 13:48:18', '2026-09-11 14:03:37', NULL),
(40, '175a1828-3c92-4016-b8ee-5555945ad36c', 'Slug Generator', 'slug-generator', 'Api for Slug Generator', '1.0.0', 'active', 2, 30, '## Slug Generator\n\nGenerate URL slugs.\n\n### Endpoint\n```\nGET /gateway/slug-generator/generator?text=Hello World!\n```', '/gateway/slug-generator', 1, 1, 0, 0, 0, '2026-09-05 13:50:32', '2026-09-11 14:03:40', NULL),
(41, 'ffd3017a-006d-43a9-a185-05f997c701e6', 'Palindrome Checker', 'palindrome-checker', 'Api for Palindrome Checker', '1.0.0', 'active', 2, 30, '## Palindrome Checker\n\nCheck if text is palindrome.\n\n### Endpoint\n```\nGET /gateway/palindrome-checker/generator?text=racecar\n```', '/gateway/palindrome-checker', 1, 1, 0, 0, 0, '2026-09-06 12:47:13', '2026-09-11 14:03:42', NULL),
(42, '8b9b7b59-f38d-48f2-b729-67088685bc85', 'Word Frequency', 'word-frequency', 'Api for Word Frequency', '1.0.0', 'active', 2, 30, '## Word Frequency\n\nCount word frequency.\n\n### Endpoint\n```\nGET /gateway/word-frequency/generator?text=hello hello world\n```', '/gateway/word-frequency', 1, 1, 0, 0, 0, '2026-09-06 12:56:43', '2026-09-11 14:03:44', NULL),
(43, 'b61746ab-5816-4eab-aa5c-279974eed68a', 'Duplicate Word Remover', 'duplicate-word-remover', 'Api for Duplicate Word Remover', '1.0.0', 'active', 2, 30, '## Duplicate Word Remover\n\nRemove duplicate words.\n\n### Endpoint\n```\nGET /gateway/duplicate-word-remover/generator?text=hello hello world\n```', '/gateway/duplicate-word-remover', 1, 1, 0, 0, 0, '2026-09-06 12:59:24', '2026-09-11 14:03:45', NULL),
