(42, 38, 'GET', '/generator', 'const text = req.query.text || \'\';\r\n\r\nif (typeof text !== \'string\') {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst characters = text.length;\r\nconst charactersWithoutSpaces = text.replace(/\\s/g, \'\').length;\r\nconst words = text.trim() === \'\' ? 0 : text.trim().split(/\\s+/).length;\r\nconst lines = text === \'\' ? 0 : text.split(/\\r\\n|\\r|\\n/).length;\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: {\r\n      characters,\r\n      characters_without_spaces: charactersWithoutSpaces,\r\n      words,\r\n      lines\r\n    },\r\n    counted_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Count words, characters, and lines in a text.', 'Count words, characters, and lines in a text.\n\n## Endpoint\n```\nGET /generator/text-counter\n```\n\n## Query Parameters\n| Parameter | Type   | Required | Description |\n| :---      | :---   | :---     | :---        |\n| `text`    | String | Yes      | The text string to analyze |\n\n## Example Usage\n\n| Parameter | Value |\n|---|---|\n| `text` | `Hello world!` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"Hello world! Welcome to the API Hub.\"},\"output\":{\"characters\":36,\"characters_without_spaces\":31,\"words\":7,\"lines\":1},\"counted_at\":\"2026-09-05T13:46:10.000Z\"},\"error\":null}', 1, '2026-09-05 13:47:29', '2026-09-11 13:29:48'),
(43, 39, 'GET', '/generator', 'const text = req.query.text;\r\nconst type = (req.query.type || \'lower\').toLowerCase();\r\n\r\nif (typeof text !== \'string\') {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nlet result = \'\';\r\nswitch (type) {\r\n  case \'upper\':\r\n    result = text.toUpperCase();\r\n    break;\r\n  case \'lower\':\r\n    result = text.toLowerCase();\r\n    break;\r\n  case \'title\':\r\n    result = text.replace(/\\w\\S*/g, (txt) => txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase());\r\n    break;\r\n  case \'camel\':\r\n    result = text.replace(/(?:^\\w|[A-Z]|\\b\\w)/g, (word, index) => index === 0 ? word.toLowerCase() : word.toUpperCase()).replace(/\\s+/g, \'\');\r\n    break;\r\n  case \'snake\':\r\n    result = text && text.match(/[A-Z]{2,}(?=[A-Z][a-z]+[0-9]*|\\b)|[A-Z]?[a-z]+[0-9]*|[A-Z]|[0-9]+/g).map(x => x.toLowerCase()).join(\'_\');\r\n    break;\r\n  case \'kebab\':\r\n    result = text && text.match(/[A-Z]{2,}(?=[A-Z][a-z]+[0-9]*|\\b)|[A-Z]?[a-z]+[0-9]*|[A-Z]|[0-9]+/g).map(x => x.toLowerCase()).join(\'-\');\r\n    break;\r\n  default:\r\n    return {\r\n      status: 400,\r\n      data: null,\r\n      error: \"Invalid case type provided (upper, lower, title, camel, snake, kebab)\"\r\n    };\r\n}\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text, type },\r\n    output: { result },\r\n    converted_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Convert text case into various formats quickly and accurately.', 'Convert text case into various formats quickly and accurately.\n\n## Endpoint\n```\nGET /generator\n```\n\n## Query Parameters\n| Parameter | Type   | Required | Description |\n| :---      | :---   | :---     | :---        |\n| `text`    | String | Yes      | The text string to convert |\n| `type`    | String | No       | Target case type (`upper`, `lower`, `title`, `camel`, `snake`, `kebab`) |\n\n## Example Usage\n\n| Parameter | Value |\n|---|---|\n| `text` | `hello world` |\n| `type` | `title` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"hello world api hub\",\"type\":\"title\"},\"output\":{\"result\":\"Hello World Api Hub\"},\"converted_at\":\"2026-09-05T13:48:06.000Z\"},\"error\":null}', 1, '2026-09-05 13:49:03', '2026-09-11 13:29:48'),
(44, 40, 'GET', '/generator', 'const text = req.query.text;\r\n\r\nif (typeof text !== \'string\' || !text.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst slug = text\r\n  .toString()\r\n  .normalize(\'NFD\')\r\n  .replace(/[\\u0300-\\u036f]/g, \'\')\r\n  .toLowerCase()\r\n  .trim()\r\n  .replace(/[^a-z0-9 ]/g, \'\')\r\n  .replace(/\\s+/g, \'-\');\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: { slug },\r\n    generated_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Generate clean URL slugs from text quickly and accurately.', 'Generate clean URL slugs from text quickly and accurately.\n\n## Endpoint\n```\nGET /generator\n```\n\n## Query Parameters\n| Parameter | Type   | Required | Description |\n| :---      | :---   | :---     | :---        |\n| `text`    | String | Yes      | The text string to convert into a slug |\n\n## Example Usage\n\n| Parameter | Value |\n|---|---|\n| `text` | `Hello World!` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"Hello World! This is a SaaS API Hub.\"},\"output\":{\"slug\":\"hello-world-this-is-a-saas-api-hub\"},\"generated_at\":\"2026-09-05T13:50:23.000Z\"},\"error\":null}', 1, '2026-09-05 13:51:15', '2026-09-11 13:29:48'),
(45, 41, 'GET', '/generator', 'const text = req.query.text;\r\n\r\nif (typeof text !== \'string\' || !text.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst cleanedText = text\r\n  .toString()\r\n  .toLowerCase()\r\n  .replace(/[^a-z0-9]/g, \'\');\r\n\r\nconst reversedText = cleanedText.split(\'\').reverse().join(\'\');\r\nconst isPalindrome = cleanedText === reversedText && cleanedText.length > 0;\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: {\r\n      is_palindrome: isPalindrome,\r\n      cleaned_text: cleanedText\r\n    },\r\n    checked_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Check if a text reads the same backward.', 'Check if a given text is a palindrome.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | The text to check for palindrome |\n\n### Response\n\nReturns an object with `input`, `is_palindrome`, `cleaned_text`, and `checked_at` fields.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `racecar` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":\"A man a plan a canal Panama\",\"is_palindrome\":true,\"cleaned_text\":\"amanaplanacanalpanama\",\"checked_at\":\"2026-09-06T12:49:18.000Z\"},\"error\":null}', 1, '2026-09-06 12:52:34', '2026-09-11 13:29:48'),
(46, 42, 'GET', '/generator', 'const text = req.query.text;\r\n\r\nif (typeof text !== \'string\' || !text.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst words = text\r\n  .toString()\r\n  .toLowerCase()\r\n  .replace(/[^a-z0-9\\s]/g, \'\')\r\n  .trim()\r\n  .split(/\\s+/)\r\n  .filter(Boolean);\r\n\r\nconst frequency = {};\r\nfor (const word of words) {\r\n  frequency[word] = (frequency[word] || 0) + 1;\r\n}\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: {\r\n      total_words: words.length,\r\n      frequency: frequency\r\n    },\r\n    analyzed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Count the frequency of each word in a text.', 'Count the frequency of each word in a given text.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | The text to analyze for word frequency |\n\n### Response\n\nReturns an object with `input`, `output`, and `analyzed_at` fields.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `hello world hello` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"hello world hello\"},\"output\":{\"total_words\":3,\"frequency\":{\"hello\":2,\"world\":1}},\"analyzed_at\":\"2026-09-06T12:57:16.000Z\"},\"error\":null}', 1, '2026-09-06 12:58:23', '2026-09-11 13:29:48'),
(47, 43, 'GET', '/generator', 'const text = req.query.text;\r\n\r\nif (typeof text !== \'string\' || !text.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst words = text\r\n  .toString()\r\n  .trim()\r\n  .split(/\\s+/);\r\n\r\nconst uniqueWords = [...new Set(words)];\r\nconst cleanedText = uniqueWords.join(\' \');\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: {\r\n      original_count: words.length,\r\n      unique_count: uniqueWords.length,\r\n      result: cleanedText\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Remove duplicate words from a text.', 'Remove duplicate words from a given text while preserving the original order.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | The text to remove duplicate words from |\n\n### Response\n\nReturns an object with `input`, `output`, and `processed_at` fields.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `hello world hello test` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"hello world hello test\"},\"output\":{\"original_count\":4,\"unique_count\":3,\"result\":\"hello world test\"},\"processed_at\":\"2026-09-06T13:00:00.000Z\"},\"error\":null}', 1, '2026-09-06 13:00:13', '2026-09-11 13:29:48'),
(48, 44, 'GET', '/generator', 'const text = req.query.text;\r\n\r\nif (typeof text !== \'string\' || !text.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst reversedText = text\r\n  .toString()\r\n  .split(\'\')\r\n  .reverse()\r\n  .join(\'\');\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: {\r\n      result: reversedText\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Reverse the character order of a text.', 'Reverse the character order of a given text.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | The text to reverse |\n\n### Response\n\nReturns an object with `input`, `output`, and `processed_at` fields.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `hello world` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"hello world\"},\"output\":{\"result\":\"dlrow olleh\"},\"processed_at\":\"2026-09-06T13:02:00.000Z\"},\"error\":null}', 1, '2026-09-06 13:02:05', '2026-09-11 13:29:48'),
(49, 45, 'GET', '/generator', 'const text = req.query.text;\r\n\r\nif (typeof text !== \'string\') {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst trimmedText = text.trim();\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: {\r\n      result: trimmedText\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Trim whitespace from the beginning and end of text.', 'Trim leading and trailing whitespace from a given text.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | The text to trim |\n\n### Response\n\nReturns an object with `input`, `output`, and `processed_at` fields.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `   hello world   ` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"   hello world   \"},\"output\":{\"result\":\"hello world\"},\"processed_at\":\"2026-09-06T13:02:45.000Z\"},\"error\":null}', 1, '2026-09-06 13:04:04', '2026-09-11 13:29:48'),
(50, 46, 'GET', '/generator', 'const text = req.query.text;\r\n\r\nif (typeof text !== \'string\' || !text.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nconst items = text.toString().includes(\'\\n\') \r\n  ? text.toString().split(/\\r?\\n/) \r\n  : text.toString().split(/\\s+/);\r\n\r\nconst sortedItems = [...items].sort((a, b) => a.localeCompare(b));\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: { text },\r\n    output: {\r\n      result: sortedItems.join(text.toString().includes(\'\\n\') ? \'\\n\' : \' \'),\r\n      items: sortedItems\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Sort lines or words in alphabetical order.', 'Sort lines or words in alphabetical order from a given text.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | The text or lines to sort |\n\n### Response\n\nReturns an object with `input`, `output`, and `processed_at` fields.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `banana<br>apple<br>cherry` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"banana\\napple\\ncherry\"},\"output\":{\"result\":\"apple\\nbanana\\ncherry\",\"lines\":[\"apple\",\"banana\",\"cherry\"]},\"processed_at\":\"2026-09-06T13:05:04.000Z\"},\"error\":null}', 1, '2026-09-06 13:06:11', '2026-09-11 13:29:48'),
(51, 47, 'GET', '/generator', 'const text = req.query.text;\r\nconst mode = String(req.query.mode || \"encode\").toLowerCase();\r\n\r\nif (typeof text !== \"string\") {\r\n    return {\r\n        status: 400,\r\n        data: null,\r\n        error: \"Invalid or missing parameters (text)\"\r\n    };\r\n}\r\n\r\nif (mode !== \"encode\" && mode !== \"decode\") {\r\n    return {\r\n        status: 400,\r\n        data: null,\r\n        error: \"Invalid mode. Allowed values: encode or decode\"\r\n    };\r\n}\r\n\r\nlet result;\r\n\r\nif (mode === \"encode\") {\r\n    result = text\r\n        .replace(/&/g, \"&amp;\")\r\n        .replace(/</g, \"&lt;\")\r\n        .replace(/>/g, \"&gt;\")\r\n        .replace(new RegExp(String.fromCharCode(34), \"g\"), \"&quot;\")\r\n        .replace(new RegExp(String.fromCharCode(39), \"g\"), \"&#39;\");\r\n} else {\r\n    result = text\r\n        .replace(/&lt;/g, \"<\")\r\n        .replace(/&gt;/g, \">\")\r\n        .replace(/&quot;/g, String.fromCharCode(34))\r\n        .replace(/&#39;/g, String.fromCharCode(39))\r\n        .replace(/&amp;/g, \"&\");\r\n}\r\n\r\nreturn {\r\n    status: 200,\r\n    data: {\r\n        input: {\r\n            text: text,\r\n            mode: mode\r\n        },\r\n        output: {\r\n            result: result\r\n        },\r\n        processed_at: new Date().toISOString()\r\n    },\r\n    error: null\r\n};', 'Encode or decode HTML entities.', 'Encode special HTML characters into entities or decode HTML entities back into normal characters.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | Text to encode or decode |\n| mode | string | No | encode or decode, default: encode |\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `<div>Hello & World</div>` |\n| `mode` | `encode` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"<div>Hello & World</div>\",\"mode\":\"encode\"},\"output\":{\"result\":\"&lt;div&gt;Hello &amp; World&lt;/div&gt;\"},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
(52, 48, 'GET', '/generator', 'const text = req.query.text;\r\nconst secret = req.query.secret;\r\nconst algorithm = (req.query.algorithm || \"sha256\").toLowerCase();\r\n\r\nif (typeof text !== \"string\" || !text) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (text)\"\r\n  };\r\n}\r\n\r\nif (typeof secret !== \"string\" || !secret) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (secret)\"\r\n  };\r\n}\r\n\r\nconst allowedAlgorithms = [\r\n  \"md5\",\r\n  \"sha1\",\r\n  \"sha224\",\r\n  \"sha256\",\r\n  \"sha384\",\r\n  \"sha512\"\r\n];\r\n\r\nif (!allowedAlgorithms.includes(algorithm)) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid algorithm. Allowed values: \" + allowedAlgorithms.join(\", \")\r\n  };\r\n}\r\n\r\nconst crypto = require(\"crypto\");\r\n\r\nconst hash = crypto\r\n  .createHmac(algorithm, secret)\r\n  .update(text)\r\n  .digest(\"hex\");\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: {\r\n      text,\r\n      algorithm\r\n    },\r\n    output: {\r\n      hmac: hash\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Generate HMAC hashes using a secret key.', 'Generate a Hash-based Message Authentication Code (HMAC).\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| text | string | Yes | Text to hash |\n| secret | string | Yes | Secret key |\n| algorithm | string | No | Hash algorithm, default: `sha256` |\n\nSupported algorithms: `md5`, `sha1`, `sha224`, `sha256`, `sha384`, `sha512`.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `text` | `hello` |\n| `secret` | `my-secret` |\n| `algorithm` | `sha256` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"text\":\"hello\",\"algorithm\":\"sha256\"},\"output\":{\"hmac\":\"c4d0b8f8d4f7c7b6a8f3b5e9d0c1a2b3\"},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
(53, 49, 'GET', '/generator', 'const min = req.query.min !== undefined ? Number(req.query.min) : 0;\r\nconst max = req.query.max !== undefined ? Number(req.query.max) : 100;\r\nconst integer = req.query.integer !== \"false\";\r\n\r\nif (!Number.isFinite(min) || !Number.isFinite(max)) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Parameters min and max must be valid numbers\"\r\n  };\r\n}\r\n\r\nif (min > max) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Parameter min cannot be greater than max\"\r\n  };\r\n}\r\n\r\nlet result;\r\n\r\nif (integer) {\r\n  result = Math.floor(Math.random() * (max - min + 1)) + min;\r\n} else {\r\n  result = Math.random() * (max - min) + min;\r\n}\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: {\r\n      min,\r\n      max,\r\n      integer\r\n    },\r\n    output: {\r\n      result\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Generate a random number.', 'Generate a random number within a specified range.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| min | number | No | Minimum value, default: `0` |\n| max | number | No | Maximum value, default: `100` |\n| integer | boolean | No | Generate integer, default: `true` |\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `min` | `1` |\n| `max` | `100` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"min\":1,\"max\":100,\"integer\":true},\"output\":{\"result\":42},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
(54, 50, 'GET', '/generator', 'const result = Math.random() >= 0.5;\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    output: {\r\n      result\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Generate a random boolean value.', 'Generate a random boolean value: `true` or `false`.', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"output\":{\"result\":true},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
(55, 51, 'GET', '/generator', 'const choices = req.query.choices;\r\n\r\nif (typeof choices !== \"string\" || !choices.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (choices)\"\r\n  };\r\n}\r\n\r\nconst items = choices\r\n  .split(\",\")\r\n  .map(item => item.trim())\r\n  .filter(Boolean);\r\n\r\nif (items.length === 0) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"At least one valid choice is required\"\r\n  };\r\n}\r\n\r\nconst index = Math.floor(Math.random() * items.length);\r\nconst result = items[index];\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: {\r\n      choices: items\r\n    },\r\n    output: {\r\n      result,\r\n      index\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Select a random item from a list of choices.', 'Select one random item from a comma-separated list.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| choices | string | Yes | Comma-separated list of choices |\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `choices` | `apple,banana,cherry,orange` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"choices\":[\"apple\",\"banana\",\"cherry\",\"orange\"]},\"output\":{\"result\":\"banana\",\"index\":1},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
(56, 52, 'GET', '/generator', 'function randomChannel() {\r\n  return Math.floor(Math.random() * 256);\r\n}\r\n\r\nconst r = randomChannel();\r\nconst g = randomChannel();\r\nconst b = randomChannel();\r\n\r\nconst hex = \"#\" + [r, g, b]\r\n  .map(value => value.toString(16).padStart(2, \"0\"))\r\n  .join(\"\")\r\n  .toUpperCase();\r\n\r\nconst rgb = \"rgb(\" + r + \", \" + g + \", \" + b + \")\";\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    output: {\r\n      hex,\r\n      rgb,\r\n      red: r,\r\n      green: g,\r\n      blue: b\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Generate a random color in HEX and RGB format.', 'Generate a random color with HEX and RGB values.', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"output\":{\"hex\":\"#3A7FBC\",\"rgb\":\"rgb(58, 127, 188)\",\"red\":58,\"green\":127,\"blue\":188},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
(57, 53, 'GET', '/generator', 'const length = req.query.length !== undefined\r\n  ? Number.parseInt(req.query.length, 10)\r\n  : 16;\r\n\r\nif (!Number.isInteger(length) || length < 1 || length > 1024) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Parameter length must be an integer between 1 and 1024\"\r\n  };\r\n}\r\n\r\nconst chars = \"0123456789ABCDEF\";\r\nlet result = \"\";\r\n\r\nfor (let i = 0; i < length; i++) {\r\n  result += chars[Math.floor(Math.random() * chars.length)];\r\n}\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: {\r\n      length\r\n    },\r\n    output: {\r\n      result\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Generate a random hexadecimal string.', 'Generate a random hexadecimal string.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| length | integer | No | Length of HEX string, default: `16`, max: `1024` |\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `length` | `32` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"length\":16},\"output\":{\"result\":\"A3F81C9E72B4D056\"},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48');
INSERT INTO `api_routes` (`id`, `api_id`, `method`, `path`, `handler_code`, `description`, `documentation`, `request_schema`, `response_schema`, `sample_response`, `is_active`, `created_at`, `updated_at`) VALUES
(58, 54, 'GET', '/generator', 'const value = req.query.number;\r\n\r\nif (value === undefined || value === null || value === \"\") {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (number)\"\r\n  };\r\n}\r\n\r\nconst number = Number(value);\r\n\r\nif (!Number.isSafeInteger(number)) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Parameter number must be a valid safe integer\"\r\n  };\r\n}\r\n\r\nconst ones = [\r\n  \"zero\", \"one\", \"two\", \"three\", \"four\",\r\n  \"five\", \"six\", \"seven\", \"eight\", \"nine\",\r\n  \"ten\", \"eleven\", \"twelve\", \"thirteen\", \"fourteen\",\r\n  \"fifteen\", \"sixteen\", \"seventeen\", \"eighteen\", \"nineteen\"\r\n];\r\n\r\nconst tens = [\r\n  \"\", \"\", \"twenty\", \"thirty\", \"forty\",\r\n  \"fifty\", \"sixty\", \"seventy\", \"eighty\", \"ninety\"\r\n];\r\n\r\nfunction convertUnderThousand(n) {\r\n  let result = \"\";\r\n\r\n  if (n >= 100) {\r\n    result += ones[Math.floor(n / 100)] + \" hundred\";\r\n    n %= 100;\r\n    if (n > 0) result += \" \";\r\n  }\r\n\r\n  if (n >= 20) {\r\n    result += tens[Math.floor(n / 10)];\r\n    if (n % 10 > 0) result += \"-\" + ones[n % 10];\r\n  } else if (n > 0) {\r\n    result += ones[n];\r\n  }\r\n\r\n  return result;\r\n}\r\n\r\nfunction numberToWords(n) {\r\n  if (n === 0) return \"zero\";\r\n  if (n < 0) return \"minus \" + numberToWords(Math.abs(n));\r\n\r\n  const units = [\r\n    { value: 1000000000000, name: \"trillion\" },\r\n    { value: 1000000000, name: \"billion\" },\r\n    { value: 1000000, name: \"million\" },\r\n    { value: 1000, name: \"thousand\" }\r\n  ];\r\n\r\n  let result = \"\";\r\n  let remaining = n;\r\n\r\n  for (const unit of units) {\r\n    if (remaining >= unit.value) {\r\n      const count = Math.floor(remaining / unit.value);\r\n      result += numberToWords(count) + \" \" + unit.name + \" \";\r\n      remaining %= unit.value;\r\n    }\r\n  }\r\n\r\n  if (remaining > 0) {\r\n    result += convertUnderThousand(remaining);\r\n  }\r\n\r\n  return result.trim();\r\n}\r\n\r\nconst result = numberToWords(number);\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: {\r\n      number\r\n    },\r\n    output: {\r\n      result\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Convert an integer number into English words.', 'Convert an integer number into its English word representation.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| number | integer | Yes | Number to convert |\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `number` | `123456` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"number\":123456},\"output\":{\"result\":\"one hundred twenty-three thousand four hundred fifty-six\"},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
(59, 55, 'GET', '/generator', 'const words = req.query.words;\r\n\r\nif (typeof words !== \"string\" || !words.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (words)\"\r\n  };\r\n}\r\n\r\nconst values = {\r\n  zero: 0,\r\n  one: 1,\r\n  two: 2,\r\n  three: 3,\r\n  four: 4,\r\n  five: 5,\r\n  six: 6,\r\n  seven: 7,\r\n  eight: 8,\r\n  nine: 9,\r\n  ten: 10,\r\n  eleven: 11,\r\n  twelve: 12,\r\n  thirteen: 13,\r\n  fourteen: 14,\r\n  fifteen: 15,\r\n  sixteen: 16,\r\n  seventeen: 17,\r\n  eighteen: 18,\r\n  nineteen: 19,\r\n  twenty: 20,\r\n  thirty: 30,\r\n  forty: 40,\r\n  fifty: 50,\r\n  sixty: 60,\r\n  seventy: 70,\r\n  eighty: 80,\r\n  ninety: 90\r\n};\r\n\r\nconst scales = {\r\n  hundred: 100,\r\n  thousand: 1000,\r\n  million: 1000000,\r\n  billion: 1000000000,\r\n  trillion: 1000000000000\r\n};\r\n\r\nconst tokens = words\r\n  .toLowerCase()\r\n  .replace(/-/g, \" \")\r\n  .replace(/\\band\\b/g, \" \")\r\n  .trim()\r\n  .split(/\\s+/);\r\n\r\nlet total = 0;\r\nlet current = 0;\r\nlet negative = false;\r\n\r\nfor (const token of tokens) {\r\n  if (token === \"minus\" || token === \"negative\") {\r\n    negative = true;\r\n    continue;\r\n  }\r\n\r\n  if (Object.prototype.hasOwnProperty.call(values, token)) {\r\n    current += values[token];\r\n    continue;\r\n  }\r\n\r\n  if (Object.prototype.hasOwnProperty.call(scales, token)) {\r\n    if (scales[token] === 100) {\r\n      current = (current || 1) * scales[token];\r\n    } else {\r\n      total += (current || 1) * scales[token];\r\n      current = 0;\r\n    }\r\n    continue;\r\n  }\r\n\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid number word: \" + token\r\n  };\r\n}\r\n\r\nconst result = total + current;\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: {\r\n      words\r\n    },\r\n    output: {\r\n      result: negative ? -result : result\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\