(60, 56, 'GET', '/generator', 'const value = req.query.value;\r\nconst mode = (req.query.mode || \"auto\").toLowerCase();\r\n\r\nif (typeof value !== \"string\" || !value.trim()) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid or missing parameters (value)\"\r\n  };\r\n}\r\n\r\nif (![\"auto\", \"to-roman\", \"to-number\"].includes(mode)) {\r\n  return {\r\n    status: 400,\r\n    data: null,\r\n    error: \"Invalid mode. Allowed values: auto, to-roman, to-number\"\r\n  };\r\n}\r\n\r\nconst romanMap = [\r\n  [1000, \"M\"],\r\n  [900, \"CM\"],\r\n  [500, \"D\"],\r\n  [400, \"CD\"],\r\n  [100, \"C\"],\r\n  [90, \"XC\"],\r\n  [50, \"L\"],\r\n  [40, \"XL\"],\r\n  [10, \"X\"],\r\n  [9, \"IX\"],\r\n  [5, \"V\"],\r\n  [4, \"IV\"],\r\n  [1, \"I\"]\r\n];\r\n\r\nfunction toRoman(number) {\r\n  if (!Number.isInteger(number) || number < 1 || number > 3999) {\r\n    return null;\r\n  }\r\n\r\n  let remaining = number;\r\n  let result = \"\";\r\n\r\n  for (const [value, symbol] of romanMap) {\r\n    while (remaining >= value) {\r\n      result += symbol;\r\n      remaining -= value;\r\n    }\r\n  }\r\n\r\n  return result;\r\n}\r\n\r\nfunction fromRoman(roman) {\r\n  const input = roman.toUpperCase();\r\n\r\n  if (!/^[MDCLXVI]+$/.test(input)) {\r\n    return null;\r\n  }\r\n\r\n  const values = {\r\n    I: 1,\r\n    V: 5,\r\n    X: 10,\r\n    L: 50,\r\n    C: 100,\r\n    D: 500,\r\n    M: 1000\r\n  };\r\n\r\n  let total = 0;\r\n\r\n  for (let i = 0; i < input.length; i++) {\r\n    const current = values[input[i]];\r\n    const next = values[input[i + 1]] || 0;\r\n\r\n    total += current < next ? -current : current;\r\n  }\r\n\r\n  if (toRoman(total) !== input) {\r\n    return null;\r\n  }\r\n\r\n  return total;\r\n}\r\n\r\nconst numericValue = Number(value);\r\nconst isNumber = /^\\d+$/.test(value.trim());\r\n\r\nlet result;\r\nlet direction;\r\n\r\nif (mode === \"to-roman\" || (mode === \"auto\" && isNumber)) {\r\n  result = toRoman(numericValue);\r\n  direction = \"number-to-roman\";\r\n\r\n  if (result === null) {\r\n    return {\r\n      status: 400,\r\n      data: null,\r\n      error: \"Number must be an integer between 1 and 3999\"\r\n    };\r\n  }\r\n} else {\r\n  result = fromRoman(value.trim());\r\n  direction = \"roman-to-number\";\r\n\r\n  if (result === null) {\r\n    return {\r\n      status: 400,\r\n      data: null,\r\n      error: \"Invalid Roman numeral\"\r\n    };\r\n  }\r\n}\r\n\r\nreturn {\r\n  status: 200,\r\n  data: {\r\n    input: {\r\n      value,\r\n      mode\r\n    },\r\n    output: {\r\n      result,\r\n      direction\r\n    },\r\n    processed_at: new Date().toISOString()\r\n  },\r\n  error: null\r\n};', 'Convert numbers to Roman numerals or Roman numerals to numbers.', 'Convert a number into a Roman numeral or convert a Roman numeral into a number.\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| value | string | Yes | Number or Roman numeral |\n| mode | string | No | `auto`, `to-roman`, or `to-number` |\n\nNumbers supported for Roman conversion: `1` to `3999`.\n\n### Example Request\n\n| Parameter | Value |\n|---|---|\n| `value` | `1994` |\n| `value` | `MCMXCIV`, `mode=to-number` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"input\":{\"value\":\"1994\",\"mode\":\"auto\"},\"output\":{\"result\":\"MCMXCIV\",\"direction\":\"number-to-roman\"},\"processed_at\":\"2026-09-08T01:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:00:00', '2026-09-11 13:29:48'),
