(62, 58, 'GET', '/generator', 'const raw = req.query.timestamp; const unit = String(req.query.unit || \"seconds\").toLowerCase(); if (raw === undefined || raw === \"\") return {status:400,data:null,error:\"timestamp is required\"}; const value = Number(raw); if (!Number.isFinite(value)) return {status:400,data:null,error:\"Invalid timestamp\"}; if (unit !== \"seconds\" && unit !== \"milliseconds\") return {status:400,data:null,error:\"Invalid unit. Allowed values: seconds or milliseconds\"}; const ms = unit === \"milliseconds\" ? value : value * 1000; const date = new Date(ms); if (Number.isNaN(date.getTime())) return {status:400,data:null,error:\"Invalid timestamp\"}; return {status:200,data:{output:{timestamp:value,unit,iso:date.toISOString(),date:date.toUTCString()},processed_at:new Date().toISOString()},error:null};', 'Convert a Unix timestamp.', 'Convert a Unix timestamp into a readable date.\n\n### Endpoint\nGET /gateway/timestamp-converter/generator\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| timestamp | number | Yes | Unix timestamp value |\n| unit | string | No | seconds or milliseconds. Default: seconds |\n\n### Example Usage\n\n| Parameter | Value |\n|---|---|\n| `timestamp` | `1757246400` |\n| `unit` | `seconds` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"output\":{\"timestamp\":1757246400,\"unit\":\"seconds\",\"iso\":\"2026-09-07T16:00:00.000Z\",\"date\":\"Mon, 07 Sep 2026 16:00:00 GMT\"},\"processed_at\":\"2026-09-07T16:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:47:06', '2026-09-11 13:29:48'),
(63, 59, 'GET', '/generator', 'const start = req.query.start; const end = req.query.end; if (!start || !end) return {status:400,data:null,error:\"start and end are required\"}; const a = new Date(start); const b = new Date(end); if (Number.isNaN(a.getTime()) || Number.isNaN(b.getTime())) return {status:400,data:null,error:\"Invalid date\"}; const milliseconds = b.getTime() - a.getTime(); return {status:200,data:{output:{milliseconds,seconds:milliseconds/1000,minutes:milliseconds/60000,hours:milliseconds/3600000,days:milliseconds/86400000,start:a.toISOString(),end:b.toISOString()},processed_at:new Date().toISOString()},error:null};', 'Calculate date difference.', 'Calculate the difference between two dates.\n\n### Endpoint\nGET /gateway/date-difference/generator\n\n### Query Parameters\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| start | string | Yes | Start date in ISO or supported date format |\n| end | string | Yes | End date in ISO or supported date format |\n\n### Example Usage\n\n| Parameter | Value |\n|---|---|\n| `start` | `2026-09-01` |\n| `end` | `2026-09-08` |', '{\"type\":\"object\",\"properties\":{}}', '{\"status\":200,\"data\":{\"result\":\"output\"},\"error\":null}', '{\"status\":200,\"data\":{\"output\":{\"milliseconds\":86400000,\"seconds\":86400,\"minutes\":1440,\"hours\":24,\"days\":1,\"start\":\"2026-09-07T00:00:00.000Z\",\"end\":\"2026-09-08T00:00:00.000Z\"},\"processed_at\":\"2026-09-08T00:00:00.000Z\"},\"error\":null}', 1, '2026-09-08 08:47:06', '2026-09-11 13:29:48'),
