--
-- Struktur dari tabel `email_otps`
--

CREATE TABLE `email_otps` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `otp_code` varchar(6) NOT NULL,
  `purpose` varchar(50) NOT NULL DEFAULT 'email_verification' COMMENT 'email_verification, password_reset, etc',
  `expires_at` datetime NOT NULL,
  `attempts` int(11) NOT NULL DEFAULT 0,
  `max_attempts` int(11) NOT NULL DEFAULT 5,
  `used` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Struktur dari tabel `key_scopes`
--

CREATE TABLE `key_scopes` (
  `id` int(11) NOT NULL,
  `api_key_id` int(11) NOT NULL,
  `api_id` int(11) NOT NULL,
  `allowed_methods` set('GET','POST','PUT','DELETE','PATCH') NOT NULL DEFAULT 'GET,POST,PUT,DELETE',
  `created_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Struktur dari tabel `notifications`
--

CREATE TABLE `notifications` (
  `id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL COMMENT 'NULL = broadcast to all admins',
  `target` enum('admin','user') NOT NULL DEFAULT 'user' COMMENT 'Which role sees this notification',
  `sender_id` int(11) DEFAULT NULL COMMENT 'Admin who sent push notification (NULL = system)',
  `type` varchar(50) NOT NULL COMMENT 'e.g. transaction_approved, new_user, credit_add, verification_pending, system_alert',
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `link` varchar(500) DEFAULT NULL COMMENT 'URL to navigate when clicked',
  `image_url` varchar(500) DEFAULT NULL,
  `icon` varchar(50) DEFAULT NULL COMMENT 'Icon name for frontend',
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `read_at` datetime DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'JSON data for extra context' CHECK (json_valid(`metadata`)),
  `created_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

